void do_group_exit(int exit_code)
{
  struct signal_struct *sig = current->signal;
  BUG_ON(exit_code & 0x80);

  if (signal_group_exit(sig))
    exit_code = sig->group_exit_code;
  else if (!thread_group_empty(current)) {
    struct signal_struct *const sig = current->signal;
    struct sighand_struct *const sighand = current->sighand;
    spin_lock_irq(&sighand->siglock);
    if (signal_group_exit(sig))
      exit_code = sig->group_exit_code;
    else {
      sig->group_exit_code = exit_code;
      zap_other_threads(current);
    }
    spin_unlock_irq(&sighand->siglock);
  }
  do_exit(exit_code);
}

NORET_TYPE void do_exit(long code)
{
  struct task_struct *tsk = current;
  int group_dead;

  profile_task_exit(tsk);

  WARN_ON(atomic_read(&tsk->fs_excl));

  if (unlikely(in_interrupt()))
    panic("Aiee, killing interrupt handler!");
  if (unlikely(!tsk->pid))
    panic("Attempted to kill the idle task!");

  /*
   * If do_exit is called because this processes oopsed, make sure
   * other processes get a chance to run before we die.
   */
  if (unlikely(tsk->flags & PF_EXITING)) {
    printk(KERN_ALERT "Fixing recursive fault but reboot is needed!\n");
    /*
     * We can do this unlocked here. The futex code uses
     * this flag just to verify whether the pi state
     * cleanup has been done or not. In the worst case
     * it loops once more.
     */
    tsk->flags |= PF_EXITPIDONE;
    set_task_state(tsk, TASK_UNINTERRUPTIBLE);
    schedule();
    BUG();
  }

  exit_signals(tsk);
  /*
   * tsk->flags are checked in the futex code to protect against
   * an unexpected task wakeup.
   */
  tsk->flags |= PF_EXITING;

  /*
   * tsk->io_context is protected by task_lock, and exit_io_context()
   * is protected by task_lock too.
   */
  exit_io_context(tsk);

  if (tsk->io_wait) {
    /*
     * We don't want the task to be frozen/hibernated while
     * it is waiting for I/O.
     */
    tsk->io_wait = 0;
  }

  if (unlikely(in_atomic()))
    printk(KERN_INFO "note: %s/%d exited with preempt_count %d\n",
      current->comm, task_pid_nr(current),
      preempt_count());

  profile_munmap(tsk->active_mm);
  group_dead = atomic_dec_and_test(&tsk->signal->live);
  if (group_dead) {
    /*
     * This accumulates the times of exited children and
     * the time of this thread.
     */
    acct_process(code);
    exit_sem(tsk);
  }
  __exit_fs(tsk);
  exit_files(tsk);
  exit_fs(tsk);
  exit_namespace(tsk);
  exit_thread();
  cpuset_exit(tsk);
  exit_keys(tsk);

  if (group_dead && tsk->signal->leader)
    disassociate_ctty(1);
  module_put(tsk->real_cred->user_ns->owner);

  /*
   * FIXME: do that only when needed, using sched_exit tracepoints
   */
  profile_handoff_task(tsk);

  /*
   * Make sure we are holding no locks:
   */
  debug_check_no_locks_held(tsk);
  /*
   * We can do this unlocked here. The futex code uses
   * this flag just to verify whether the pi state
   * cleanup has been done or not.
   */
  tsk->flags |= PF_EXITPIDONE;

  if (group_dead) {
    hrtimer_cancel(&tsk->signal->real_timer);
    exit_itimers(tsk->signal);
    exit_posix_timers(tsk);
  }

  exit_mm(tsk);

  /*
   * The setting of the task state to TASK_DEAD must be
   * the last thing the task does before it is reaped.
   */
  if (group_dead)
    acct_update_integrals(tsk);
  update_rusage(tsk, RUSAGE_CHILDREN);
  tsk->exit_code = code;
  /*
   * We're in the middle of terminating, and setting the state
   * to TASK_DEAD. The task must not try to acquire any locks,
   * or do anything else that could block.
   */
  set_task_state(tsk, TASK_DEAD);
  /*
   * The final call to schedule() will switch to another task.
   * The task will never run again.
   */
  schedule();
  BUG();
  /*
   * schedule() should never return.
   */
  for (;;)
    ;
}

static void exit_signals(struct task_struct *tsk)
{
  int group_stop = 0;
  struct signal_struct *sig = tsk->signal;

  /*
   * The thread group leader is the only one that can report
   * the exit status to the parent.
   */
  if (thread_group_empty(tsk) || signal_group_exit(sig)) {
    tsk->flags |= PF_EXITING;
    if (thread_group_leader(tsk)) {
      /*
       * If this is the thread group leader, then we
       * are the last thread in the group.
       */
      sig->group_exit_code = tsk->exit_code;
      group_stop = tracehook_notify_death(tsk, &group_exit_code, NULL);
    }
  }
}

void exit_mm(struct task_struct * tsk)
{
  struct mm_struct *mm = tsk->mm;

  mm_release(tsk, mm);
  if (!mm)
    return;
  /*
   * Serialize with any possible pending coredump.
   * We must hold mmap_sem around checking core_state
   * and clearing tsk->mm.  The core_indirect_mutex
   * protects against multiple parallel coredumps.
   */
  down_read(&mm->mmap_sem);
  if (mm->core_state) {
    up_read(&mm->mmap_sem);
    /*
     * If the process is coredumping, we can't release
     * the mm yet.
     */
    return;
  }
  BUG_ON(mm != tsk->active_mm);
  /* more_yank */
  tsk->mm = NULL;
  tsk->active_mm = NULL;
  up_read(&mm->mmap_sem);
  enter_lazy_tlb(mm, tsk);
  mmput(mm);
}

void mmput(struct mm_struct *mm)
{
  might_sleep();

  if (atomic_dec_and_test(&mm->mm_users)) {
    uprobe_clear_state(mm);
    exit_aio(mm);
    ksm_exit(mm);
    khugepaged_exit(mm); /* must run before exit_mmap */
    exit_mmap(mm);
    set_mm_exe_file(mm, NULL);
    if (!list_empty(&mm->mmlist)) {
      spin_lock(&mmlist_lock);
      list_del(&mm->mmlist);
      spin_unlock(&mmlist_lock);
    }
    put_swap_token(mm);
    mmdrop(mm);
  }
}

void exit_mmap(struct mm_struct *mm)
{
  struct mmu_gather tlb;
  struct vm_area_struct *vma;
  unsigned long nr_accounted = 0;
  unsigned long end;

  lru_add_drain();
  spin_lock(&mm->page_table_lock);
  tlb_gather_mmu(&tlb, mm, 0, -1);
  /* update_hiwater_rss(mm) here? */
  end = unmap_vmas(&tlb, mm, mm->mmap, 0,
      TASK_SIZE, &nr_accounted, NULL);
  /*
   * mm->mmap is set to NULL during the unmap_vmas call.
   */
  vma = mm->mmap;
  mm->mmap = NULL;
  mm->mm_rb = RB_ROOT;
  mm->mmap_cache = NULL;
  calc_vm_flags(mm);
  spin_unlock(&mm->page_table_lock);
  flush_tlb_mm(mm);

  /*
   * Walk the list again to free the actual vma structures.
   */
  while (vma) {
    struct vm_area_struct *next = vma->vm_next;
    remove_vma(vma);
    vma = next;
  }
  lru_add_drain();
  /*
   * Walk the list again to free the actual vma structures.
   */
  tlb_finish_mmu(&tlb, 0, end);
}

void exit_files(struct task_struct *tsk)
{
  struct files_struct * files = tsk->files;

  if (files) {
    task_lock(tsk);
    tsk->files = NULL;
    task_unlock(tsk);
    put_files_struct(files);
  }
}

void put_files_struct(struct files_struct *files)
{
  struct fdtable *fdt;

  if (atomic_dec_and_test(&files->count)) {
    close_files(files);
    /*
     * Free the fdtables and the files structure itself.
     */
    fdt = files_fdtable(files);
    if (fdt != &files->fdtab)
      __free_fdtable(fdt);
    kmem_cache_free(files_cachep, files);
  }
}

static void close_files(struct files_struct * files)
{
  int i, j;
  struct fdtable *fdt;

  j = 0;

  /*
   * It is safe to dereference the fd table without RCU or
   * ->file_lock because this is the last reference to the
   * files_struct and we are the only user.
   */
  fdt = files_fdtable(files);
  for (;;) {
    unsigned long set;
    i = j * BITS_PER_LONG;
    if (i >= fdt->max_fds)
      break;
    set = fdt->open_fds->fds_bits[j++];
    while (set) {
      if (set & 1) {
        struct file * file = xchg(&fdt->fd[i], NULL);
        if (file) {
          filp_close(file, files);
        }
      }
      i++;
      set >>= 1;
    }
  }
}

static void do_notify_parent(struct task_struct *tsk, int sig)
{
  struct siginfo info;
  unsigned long flags;
  struct sighand_struct *sighand;

  BUG_ON(sig == -1);

  /* do_notify_parent_cldstop should have been called instead.  */
  BUG_ON(task_is_stopped_or_traced(tsk));

  info.si_signo = sig;
  info.si_errno = 0;
  /*
   * FIXME: under some circumstances, we should use CLD_KILLED
   * instead of CLD_EXITED.
   */
  info.si_code = CLD_EXITED;
  info.si_pid = task_pid_nr_ns(tsk, tsk->parent->nsproxy->pid_ns);
  info.si_uid = task_uid(tsk);
  info.si_status = tsk->exit_code >> 8;
  info.si_utime = cputime_to_clock_t(tsk->utime);
  info.si_stime = cputime_to_clock_t(tsk->stime);

  sighand = tsk->parent->sighand;
  spin_lock_irqsave(&sighand->siglock, flags);
  if (sighand->action[SIGCHLD-1].sa.sa_handler == SIG_IGN ||
      (sighand->action[SIGCHLD-1].sa.sa_flags & SA_NOCLDWAIT))
    tsk->exit_signal = -1;
  if (sigismember(&sighand->action[SIGCHLD-1].sa.sa_mask, sig))
    sig = SIGCHLD;
  __group_send_sig_info(sig, &info, tsk->parent);
  spin_unlock_irqrestore(&sighand->siglock, flags);
}

static void wake_up_parent(struct task_struct *parent, struct task_struct *child)
{
  wake_up_interruptible(&parent->signal->wait_chldexit);
}

typedef struct siginfo {
  int si_signo;
  int si_errno;
  int si_code;

  union {
    int _pad[SI_PAD_SIZE];

    /* kill() */
    struct {
      pid_t _pid;	/* sender's pid */
      __ARCH_SI_UID_T _uid;	/* sender's uid */
    } _kill;

    /* POSIX.1b timers */
    struct {
      unsigned int _timer1;
      unsigned int _timer2;
    } _timer;

    /* SIGCHLD */
    struct {
      pid_t _pid;	/* which child */
      __ARCH_SI_UID_T _uid;
      int _status;	/* exit code */
      clock_t _utime;
      clock_t _stime;
    } _sigchld;
    /* ... */
  } _sifields;
} siginfo_t;

void release_task(struct task_struct * p)
{
  struct task_struct *leader;
  int zap_leader;
repeat:
  /*
   * Make sure we don't race with anything trying to
   * wake this task up.
   */
  tracehook_prepare_release_task(p);
  if (unlikely(tsk->flags & PF_EXITING))
    return;

  /*
   * If we are the thread group leader, then we need to
   * reap the other threads in the group.
   */
  write_lock_irq(&tasklist_lock);
  if (unlikely(p->ptrace)) {
    __ptrace_unlink(p);
    if (p->exit_state != EXIT_ZOMBIE) {
      /*
       * If the task is not a zombie, then it is
       * ptraced and we need to notify the tracer.
       */
      __ptrace_unlink(p);
      goto repeat;
    }
  }

  __exit_signal(p);

  /*
   * If we are the thread group leader, and the only
   * thread in the group, then we can free the signal
   * struct.
   */
  leader = p->group_leader;
  if (leader != p && thread_group_empty(leader)
      && leader->exit_state == EXIT_ZOMBIE) {
    /*
     * If the thread group leader is a zombie,
     * then we can reap it now.
     */
    p = leader;
    goto repeat;
  }

  /*
   * If the parent has set SIG_IGN for SIGCHLD or
   * SA_NOCLDWAIT, we can reap the child immediately.
   */
  zap_leader = (leader != p && thread_group_empty(leader));
  write_unlock_irq(&tasklist_lock);
  release_thread(p);
  tracehook_report_death(p, &cookie, zap_leader);
  /*
   * We are the only user of the task_struct now,
   * so we can free it.
   */
  put_task_struct(p);
}

void zap_pid_ns_processes(struct pid_namespace *pid_ns)
{
  int nr;
  int rc;
  struct task_struct *task, *me = current;

  /*
   * The last thread in the namespace is exiting.
   * We need to kill all the other threads.
   */
  rc = me->signal->group_exit_code;
  /*
   * Don't allow any pid allocations beyond this point.
   */
  pid_ns->nr_hashed = PIDMAP_ENTRIES;

  /*
   * Send SIGKILL to all processes in the namespace.
   */
  read_lock(&tasklist_lock);
  nr = next_pidmap(pid_ns, 1);
  while (nr > 0) {
    rcu_read_lock();
    task = pid_task(find_vpid(nr), PIDTYPE_PID);
    if (task)
      send_sig_info(SIGKILL, SEND_SIG_FORCED, task);
    rcu_read_unlock();
    nr = next_pidmap(pid_ns, nr);
  }
  read_unlock(&tasklist_lock);
}

void free_pid(struct pid *pid)
{
  /* We can be called with write_lock_irq(&tasklist_lock) held */
  int i;
  unsigned long flags;

  spin_lock_irqsave(&pidmap_lock, flags);
  for (i = 0; i < pid->level; i++) {
    struct upid *upid = pid->numbers + i;
    pidmap_dealloc(upid->nr, upid->ns);
  }
  spin_unlock_irqrestore(&pidmap_lock, flags);

  kmem_cache_free(pid_cachep, pid);
}

SYSCALL_DEFINE4(wait4, pid_t, upid, int __user *, stat_addr,
    int, options, struct rusage __user *, ru)
{
  struct wait_opts wo;
  struct pid *pid = NULL;
  enum pid_type type;
  long ret;

  if (options & ~(WNOHANG|WUNTRACED|WCONTINUED|
      __WNOTHREAD|__WCLONE|__WALL))
    return -EINVAL;

  if (upid == -1)
    type = PIDTYPE_MAX;
  else if (upid < 0) {
    type = PIDTYPE_PGID;
    pid = find_get_pid(-upid);
  } else if (upid == 0) {
    type = PIDTYPE_PGID;
    pid = find_get_pid(task_pgrp_nr(current));
  } else /* upid > 0 */ {
    type = PIDTYPE_PID;
    pid = find_get_pid(upid);
  }

  wo.wo_type = type;
  wo.wo_pid = pid;
  wo.wo_options = options;
  wo.wo_stat_addr = stat_addr;
  wo.wo_rusage_addr = ru;
  ret = do_wait(&wo);
  put_pid(pid);

  /* avoid REGPARM breakage on x86: */
  return ret;
}

static long do_wait(struct wait_opts *wo)
{
  struct task_struct *tsk;
  int flag;
  pid_t pid;
  struct list_head *q;

  trace_sched_process_wait(wo->wo_pid);

  repeat:
  flag = 0;
  list_for_each_entry(tsk, &current->children, sibling) {
    int ret;
    pid = task_pid_nr_ns(tsk, current->nsproxy->pid_ns);
    ret = eligible_child(wo, tsk);
    if (!ret)
      continue;
    switch (ret) {
    case ERR_PTR(-EAGAIN):
      flag = 1;
      continue;
    case ERR_PTR(-ECHILD):
      goto notask;
    }
    /*
     * We have a matching child.
     */
    if (tsk->exit_state == EXIT_ZOMBIE) {
      /*
       * We don't reap group leaders with sub-threads.
       */
      if (!likely(wo->wo_options & WEXITED))
        continue;
      pid = wo->wo_stat_addr ?
        tsk->exit_code : 0;
      if (likely(!wo->wo_stat_addr ||
          !put_user(pid, wo->wo_stat_addr))) {
        if (wo->wo_rusage_addr)
          getrusage(tsk, RUSAGE_BOTH,
              wo->wo_rusage_addr);
        if (!wo->wo_pid || type != PIDTYPE_PID ||
            wo->wo_pid == pid) {
          release_task(tsk);
          return pid;
        }
      }
    }
    /* ... */
  }
notask:
  /*
   * No matching child found.
   */
  if (flag) {
    pid = 0;
    if (wo->wo_options & WNOHANG)
      return 0;
    /*
     * Wait for a child to exit.
     */
    retval = -ERESTARTSYS;
    if (signal_pending(current))
      goto end;
    __set_current_state(TASK_INTERRUPTIBLE);
    schedule();
    goto repeat;
  }
end:
  return pid;
}
